    aeo: [{"pergunta":"O que aconteceu?","resposta":"Candidato a presidente cita insegurança jurídica e carga tributária e promete reduzir impostos e burocracia"},{"pergunta":"Qual é o ponto principal?","resposta":"O candidato à Presidência Flávio Bolsonaro (PL) afirmou nesta 3ª feira (6.out.2026) que o presidente Luiz Inácio Lula da Silva (PT) não teria condições de atrair investimentos para o Brasil. Também chamou o petista de “biruta” ao criticar sua atuação na Presidência. A declaração foi dada em Brasília, depois de uma reunião com o governador de São Paulo, Tarcí"},{"pergunta":"Quais são os dados mais importantes?","resposta":"Flávio disse que, se eleito, pretende reduzir a carga tributária sobre a folha de pagamento, diminuir impostos e burocracia e criar um ambiente que, segundo ele, favoreça a entrada de empresas no país."},{"pergunta":"Qual é o contexto?","resposta":"“Eu quero reduzir a carga tributária em cima da folha de pagamento, ou seja, o dinheiro do trabalhador vai ficar mais com o trabalhador do que com o governo. Eu vou fazer para reduzir impostos, reduzir burocracia. Eu vou criar um ambiente de negócio favorável aqui no país para que as empresas voltem para cá com força”, afirmou."},{"pergunta":"Quais são os próximos desdobramentos?","resposta":"O senador atribuiu a Lula a perda de credibilidade do Brasil entre investidores e disse que o petista muda de posição conforme as circunstâncias."}],
